"use strict";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useLockContract } from "hooks/useLockContract";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useCallback, useState, useEffect } from "react";
import { calculateVotingPowerFromDays, getLockDurationConstraints, parseAmountToBigint, parseLockAmount, getEpochLockDuration } from "utils/lockCalculations";
import { useAccount } from "wagmi";
export function useCreateLockFlow() {
  const { address: account } = useAccount();
  const { refetch: refetchUserLocks } = useVeABXUserLocks(account);
  const {
    approveABX,
    createLock,
    createLockBatched,
    needsApproval,
    getFormattedABXBalance,
    isWritePending,
    isConfirming,
    isSuccess,
    writeError,
    transactionHash,
    refetchAllowance,
    supportsEip5792,
    abxBalance,
    abxTokenDecimals
  } = useLockContract();
  const [formState, setFormState] = useState({
    amount: "",
    lockDurationInDays: getEpochLockDuration(1),
    // Default to first epoch (handles Wednesday edge case)
    isValid: false,
    errors: {}
  });
  const [flowState, setFlowState] = useState({
    step: "input"
  });
  const [batchId, setBatchId] = useState(null);
  const validateForm = useCallback((amount, durationInDays) => {
    const errors = {};
    const amountValidation = parseLockAmount(amount);
    if (!amountValidation.isValid) {
      errors.amount = amountValidation.error;
    } else {
      const userBalance = abxBalance ?? parseAmountToBigint(getFormattedABXBalance(), abxTokenDecimals);
      const requestedAmount = parseAmountToBigint(amount, abxTokenDecimals);
      if (requestedAmount === null || userBalance === null) {
        errors.amount = "Invalid amount";
      } else if (requestedAmount > userBalance) {
        errors.amount = "Insufficient ABX balance";
      }
    }
    const { maxDays } = getLockDurationConstraints();
    if (durationInDays > maxDays) {
      errors.duration = `Maximum lock duration is ${maxDays} days`;
    }
    return {
      amount,
      lockDurationInDays: durationInDays,
      isValid: Object.keys(errors).length === 0,
      errors
    };
  }, [abxBalance, abxTokenDecimals, getFormattedABXBalance]);
  const updateFormState = useCallback((updates) => {
    setFormState((current) => {
      const newAmount = updates.amount ?? current.amount;
      const newDuration = updates.lockDurationInDays ?? current.lockDurationInDays;
      return validateForm(newAmount, newDuration);
    });
  }, [validateForm]);
  const getVotingPowerPreview = useCallback(() => {
    if (!formState.isValid) return "0";
    return calculateVotingPowerFromDays(formState.amount, formState.lockDurationInDays);
  }, [formState]);
  const resetFlow = useCallback(() => {
    setFlowState({ step: "input" });
    setLastTransactionStep(null);
    setBatchId(null);
    setFormState({
      amount: "",
      lockDurationInDays: getEpochLockDuration(1),
      isValid: false,
      errors: {}
    });
  }, []);
  const executeApproval = useCallback(async () => {
    if (!formState.isValid) return;
    setFlowState({ step: "approve" });
    setLastTransactionStep("approve");
    try {
      await approveABX(formState.amount);
    } catch (error) {
      console.error("Approval failed:", error);
      const errorMessage = error instanceof Error ? error.message : "Failed to approve ABX tokens";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Token approval was cancelled by user",
            action: "create"
          }
        }, `lock-approve-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Token Approval Failed",
            description: `Failed to approve ABX tokens: ${errorMessage}`,
            action: "create"
          }
        }, `lock-approve-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
    }
  }, [formState, approveABX]);
  const handleSuccess = useCallback(async () => {
    setFlowState({
      step: "success",
      transactionHash
    });
    popupRegistry.addPopup({
      type: PopupType.LockSuccess,
      content: {
        type: "success",
        title: "Lock Created Successfully",
        description: `Successfully locked ${formState.amount} ABX for ${formState.lockDurationInDays} days`,
        hash: transactionHash,
        action: "create"
      }
    }, `lock-create-${transactionHash}`, 8e3);
    await Promise.all([
      refetchUserLocks(),
      refetchAllowance()
    ]);
  }, [transactionHash, refetchUserLocks, refetchAllowance, formState.amount, formState.lockDurationInDays]);
  const executeBatchedCreateLock = useCallback(async () => {
    if (!formState.isValid) return;
    setFlowState({ step: "create" });
    setLastTransactionStep("create");
    try {
      const id = await createLockBatched({
        amount: formState.amount,
        lockDurationInDays: formState.lockDurationInDays
      });
      setBatchId(id);
      setFlowState((current) => ({
        ...current,
        step: "confirming",
        transactionHash: id
      }));
      setTimeout(() => {
        handleSuccess();
      }, 3e3);
    } catch (error) {
      console.error("Batched create lock failed:", error);
      const errorMessage = error instanceof Error ? error.message : "Failed to create lock";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Batched lock creation was cancelled by user",
            action: "create"
          }
        }, `lock-batched-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Batched Lock Creation Failed",
            description: `Failed to create batched lock: ${errorMessage}`,
            action: "create"
          }
        }, `lock-batched-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
      setBatchId(null);
    }
  }, [formState, createLockBatched, handleSuccess]);
  const executeCreateLock = useCallback(async () => {
    if (!formState.isValid) return;
    setFlowState({ step: "create" });
    setLastTransactionStep("create");
    try {
      await createLock({
        amount: formState.amount,
        lockDurationInDays: formState.lockDurationInDays
      });
    } catch (error) {
      console.error("Create lock failed:", error);
      const errorMessage = error instanceof Error ? error.message : "Failed to create lock";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Lock creation was cancelled by user",
            action: "create"
          }
        }, `lock-create-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Lock Creation Failed",
            description: `Failed to create lock: ${errorMessage}`,
            action: "create"
          }
        }, `lock-create-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
    }
  }, [formState, createLock]);
  const executeFlow = useCallback(async () => {
    if (!formState.isValid || !account) return;
    if (supportsEip5792 && needsApproval(formState.amount)) {
      await executeBatchedCreateLock();
    } else if (needsApproval(formState.amount)) {
      await executeApproval();
    } else {
      await executeCreateLock();
    }
  }, [formState, account, needsApproval, supportsEip5792, executeBatchedCreateLock, executeApproval, executeCreateLock]);
  const [lastTransactionStep, setLastTransactionStep] = useState(null);
  useEffect(() => {
    if (isConfirming) {
      setFlowState((current) => ({
        ...current,
        step: "confirming",
        transactionHash
      }));
    } else if (isSuccess && lastTransactionStep) {
      if (lastTransactionStep === "approve") {
        setLastTransactionStep(null);
        setTimeout(() => {
          refetchAllowance().then(() => {
            executeCreateLock();
          });
        }, 1e3);
      } else if (lastTransactionStep === "create") {
        setLastTransactionStep(null);
        handleSuccess();
      }
    } else if (writeError) {
      const errorMessage = writeError.message;
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        setFlowState({ step: "input" });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: "Lock creation was cancelled by user",
            action: "create"
          }
        }, `lock-create-cancelled-${Date.now()}`, 5e3);
      } else {
        setFlowState({
          step: "error",
          error: errorMessage
        });
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Lock Creation Failed",
            description: `Failed to create lock: ${errorMessage}`,
            action: "create"
          }
        }, `lock-create-error-${Date.now()}`, 1e4);
      }
      setLastTransactionStep(null);
    }
  }, [isConfirming, isSuccess, writeError, transactionHash, lastTransactionStep, handleSuccess, executeCreateLock, refetchAllowance]);
  return {
    // Form state
    formState,
    updateFormState,
    // Flow state  
    flowState,
    resetFlow,
    // Actions
    executeFlow,
    executeApproval,
    executeCreateLock,
    executeBatchedCreateLock,
    // Computed values
    votingPowerPreview: getVotingPowerPreview(),
    userABXBalance: getFormattedABXBalance(),
    needsApproval: formState.isValid ? needsApproval(formState.amount) : false,
    // Loading states
    isProcessing: isWritePending || isConfirming,
    // Batching support
    supportsEip5792,
    batchId,
    abxTokenDecimals,
    abxBalance,
    // Account
    isConnected: !!account
  };
}
